template <typename T = int>
T default_type(T val = {}) {
    return val;
}

int a = default_type(5);       // T=int deduced
float b = default_type<float>(); // T=float explicit (val=0.0f)

template <int N = 5>
int non_type_default(int x) {
    return x * N;
}

int m1 = non_type_default(10);   // N=5 (default)
int m2 = non_type_default<3>(10); // N=3 (explicit)

template <typename T, typename U = long>
U deduction_vs_default(T input) {
    return static_cast<U>(input);
}

long l1 = deduction_vs_default(100);     // T=int deduced, U=long default
char c1 = deduction_vs_default<int, char>(65); // T=int, U=char explicit
short s1 = deduction_vs_default<double>(5.5); // T=double deduced, U=long default
